import urllib.request, urllib.parse, json, re

def get_json(url, params=None, timeout=20):
    if params:
        url += ('&' if '?' in url else '?') + urllib.parse.urlencode(params)
    req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'})
    with urllib.request.urlopen(req,timeout=timeout) as r:
        return json.loads(r.read().decode('utf-8','replace'))

portal='https://geo.salvador.ba.gov.br/portal/sharing/rest/search'
terms=['curva de nivel','curvas de nivel','altimetria','ponto cotado','pontos cotados','topografia','topografico','SICAD','cartografia 2017','cartografia 2016','MDT 2017','modelo digital terreno','laser scanner','levantamento aerofotogrametrico','relevo']
hits={}
for q in terms:
    try:
        d=get_json(portal,{'q':q,'num':100,'f':'json'})
        print('PORTAL_QUERY',q,'TOTAL',d.get('total',0))
        for it in d.get('results',[]):
            owner=(it.get('owner') or '')
            title=it.get('title') or ''
            url=it.get('url')
            typ=it.get('type')
            tags=it.get('tags') or []
            text=' '.join([title,owner,typ or '',url or '',' '.join(tags)]).lower()
            if owner.upper().startswith(('GEO_','PMS','SEDUR','FMLF')) or any(k in text for k in ['salvador','altim','topograf','curva','sicad','mdt','relevo']):
                hits[it.get('id')]=(title,typ,owner,url,tags)
    except Exception as e: print('PORTAL_ERR',q,type(e).__name__,str(e)[:140])

print('PORTAL_RELEVANT',len(hits))
for iid,(title,typ,owner,url,tags) in sorted(hits.items(), key=lambda kv:(kv[1][2],kv[1][0])):
    print('ITEM',json.dumps({'id':iid,'title':title,'type':typ,'owner':owner,'url':url,'tags':tags},ensure_ascii=False))

roots=['https://geo.salvador.ba.gov.br/server/rest/services','https://geo.salvador.ba.gov.br/arcgis/rest/services','https://geo.salvador.ba.gov.br/geoserver/rest/services']
for root in roots:
    try:
        d=get_json(root,{'f':'json'})
        print('REST_ROOT',root,'folders',d.get('folders'),'services',len(d.get('services',[])))
        folders=d.get('folders') or []
        queue=[('',d)]
        for folder in folders:
            try:
                fd=get_json(root+'/'+urllib.parse.quote(folder),{'f':'json'})
                queue.append((folder,fd))
