                if any(k in low for k in ['topo','altim','curva','nivel','sicad','cota','relevo','terreno','mdt','cartograf']):
                    print('SERVICE_MATCH',json.dumps(s,ensure_ascii=False))
    except Exception as e:
        print('REST_ROOT_ERR',root,type(e).__name__,str(e)[:160])
